  writePdfMarkdownToVaultDesc: "\uAE30\uBCF8\uAC12\uC740 \uAEBC\uC9D0. \uCF1C\uBA74 \uAC01 PDF \uBCC0\uD658 \uACB0\uACFC\uAC00 \uC6D0\uBCF8 PDF \uC606\uC5D0 \u300C<basename>.pdf.md\u300D \uD30C\uC77C\uB85C \uAE30\uB85D\uB429\uB2C8\uB2E4. \uAEBC\uC838 \uC788\uC73C\uBA74(\uCE90\uC2DC \uC804\uC6A9 \uC544\uD0A4\uD14D\uCC98) \uACB0\uACFC\uB294 \uD50C\uB7EC\uADF8\uC778 \uCE90\uC2DC\uC5D0\uB9CC \uB0A8\uACE0 Vault\uC5D0\uB294 \uAD6C\uD604 \uC544\uD2F0\uD329\uD2B8\uB97C \uB0A8\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
  ingestRejectedSummary: "{count}\uAC1C \uD30C\uC77C\uC744 \uAC74\uB108\uB6F0\uC5C8\uC2B5\uB2C8\uB2E4(\uBE44\uC5B4 \uC788\uC74C, \uC911\uBCF5 \uB610\uB294 \uBBF8\uC9C0\uC6D0 \uD615\uC2DD).",
  reingestConfirmTitle: "\uC774 \uD30C\uC77C\uC744 \uB2E4\uC2DC \uAC00\uC838\uC62C\uAE4C\uC694?",
  reingestConfirmBody: "\u300C{filename}\u300D\uC758 \uB0B4\uC6A9\uC774 \uC774\uBBF8 \uC704\uD0A4\uC5D0 \uC788\uC2B5\uB2C8\uB2E4. \uADF8\uB798\uB3C4 \uB2E4\uC2DC \uAC00\uC838\uC62C\uAE4C\uC694?",
  reingestConfirmYes: "\uB2E4\uC2DC \uAC00\uC838\uC624\uAE30",
  reingestConfirmNo: "\uAC74\uB108\uB6F0\uAE30",
  lintDedupIncludeSourcesName: "\uC911\uBCF5 \uAC80\uC0AC\uC5D0 \uC18C\uC2A4 \uD3EC\uD568",
  lintDedupIncludeSourcesDesc: "\uAE30\uBCF8\uAC12\uC740 \uCF1C\uC9D0. \uCF1C\uC838 \uC788\uC73C\uBA74 \uBCF8\uBB38\uC774 \uB3D9\uC77C\uD55C \uC18C\uC2A4\uAC00 lint\uC5D0\uC11C \uC911\uBCF5\uC73C\uB85C \uD45C\uC2DC\uB429\uB2C8\uB2E4. \uC18C\uC2A4 \uBAA8\uC74C\uC9D1\uC5D0\uC11C \uC624\uD0D0\uC774 \uB9CE\uC73C\uBA74 \uB044\uC138\uC694.",
  // Issue #514: opt-in candidate gate (bottom Advanced settings panel).
  skipMentionOnlyCandidatesName: "\uC18C\uC2A4\uAC00 \uC5B8\uAE09\uB9CC \uD558\uB294 \uD6C4\uBCF4 \uAC74\uB108\uB6F0\uAE30",
  skipMentionOnlyCandidatesDesc: "\uAE30\uBCF8\uAC12\uC740 \uAEBC\uC9D0. \uCF1C\uBA74 \uB178\uD2B8 \uBCF8\uBB38\uC5D0 \uC774\uB984\uC774 \uB098\uD0C0\uB098\uC9C0 \uC54A\uB294 \uCD94\uCD9C \uC5D4\uD2F0\uD2F0\xB7\uAC1C\uB150(\uC5C6\uAC70\uB098 \uAD04\uD638\xB7\uC5F4\uAC70\xB7\uC9E7\uC740 \uBAA9\uB85D \uD56D\uBAA9 \uC548\uC5D0\uB9CC \uC788\uB294 \uACBD\uC6B0)\uC740 \uD398\uC774\uC9C0\uB97C \uB9CC\uB4E4\uC9C0 \uC54A\uACE0 \uCD94\uAC00 \uBAA8\uB378 \uD638\uCD9C\uB3C4 \uD558\uC9C0 \uC54A\uC73C\uBA70, \uB2E4\uB978 \uD6C4\uBCF4\uC758 \uAD00\uB828 \uBAA9\uB85D\uC5D0\uC11C\uB3C4 \uC81C\uAC70\uB429\uB2C8\uB2E4. \uB2E8\uC5B4 \uACBD\uACC4 \uD504\uB85C\uD544\uC774 \uC788\uB294 \uC704\uD0A4 \uC5B8\uC5B4\uC5D0\uC11C \uB3D9\uC791\uD569\uB2C8\uB2E4(\uB3C5\uC77C\uC5B4 \uCE21\uC815\uB428; \uC601\uC5B4\xB7\uD504\uB791\uC2A4\uC5B4\xB7\uC2A4\uD398\uC778\uC5B4\xB7\uD3EC\uB974\uD22C\uAC08\uC5B4\xB7\uB124\uB35C\uB780\uB4DC\uC5B4\uB294 \uCD94\uC815). \uB2E4\uB978 \uC5B8\uC5B4\uC5D0\uC11C\uB294 \uC801\uC6A9\uD560 \uC218 \uC5C6\uB2E4\uACE0 \uC218\uC9D1 \uC2DC \uD55C \uBC88 \uC54C\uB9BD\uB2C8\uB2E4. \uC6A9\uC5B4\uC9D1\uD615 \uBCFC\uD2B8\uB098 \uAE00\uBA38\uB9AC \uAE30\uD638 \uC704\uC8FC\uC758 \uB178\uD2B8\uC5D0\uC11C \uC5B8\uAE09\uB41C \uBAA8\uB4E0 \uC6A9\uC5B4\uB97C \uD398\uC774\uC9C0\uB85C \uB9CC\uB4E4\uACE0 \uC2F6\uB2E4\uBA74 \uAEBC \uB450\uC138\uC694.",
  createStubsForUnresolvableLinksName: "\uD574\uACB0\uB418\uC9C0 \uC54A\uB294 \uB9C1\uD06C\uC758 \uC2A4\uD141 \uD398\uC774\uC9C0 \uB9CC\uB4E4\uAE30",
  createStubsForUnresolvableLinksDesc: "\uAE30\uBCF8\uAC12\uC740 \uCF1C\uC9D0. \uAE68\uC9C4 \uB9C1\uD06C \uC218\uC815\uC774 \uB9C1\uD06C\uB97C \uC5B4\uB5A4 \uAE30\uC874 \uD398\uC774\uC9C0\uB85C\uB3C4 \uD574\uACB0\uD558\uC9C0 \uBABB\uD558\uBA74 \uBE48 \uC790\uB9AC \uD45C\uC2DC \uD398\uC774\uC9C0\uB97C \uC791\uC131\uD558\uACE0 \uB9C1\uD06C\uB97C \uADF8\uCABD\uC73C\uB85C \uB2E4\uC2DC \uC5F0\uACB0\uD569\uB2C8\uB2E4(LLM\uC73C\uB85C \uCC44\uC6B0\uC9C0 \uC54A\uC74C). \uB044\uBA74 \uC774\uB7F0 \uB9C1\uD06C\uB294 \uADF8\uB300\uB85C \uC720\uC9C0\uB418\uC5B4 \uC2E4\uC81C \uC18C\uC2A4\uAC00 \uC815\uC758\uD560 \uB54C\uAE4C\uC9C0 \uB9E4\uBC88 \uBCF4\uACE0\uC11C\uC5D0 \uD45C\uC2DC\uB429\uB2C8\uB2E4.",
