  disableThinkingName: "\uC0DD\uAC01 \uBE44\uD65C\uC131\uD654",
  disableThinkingDesc: "\uBAA8\uB378 \uC751\uB2F5\uC758 \uC0AC\uACE0 \uC5F0\uC1C4/\uCD94\uB860 \uD14D\uC2A4\uD2B8 \uCD9C\uB825\uC744 \uB055\uB2C8\uB2E4. \uAE30\uBCF8\uAC12\uC740 \uAEBC\uC838 \uC788\uC73C\uBA70, \uBAA8\uB378\uC774 \uCD94\uB860 \uD45C\uC2DC \uC5EC\uBD80\uB97C \uC2A4\uC2A4\uB85C \uACB0\uC815\uD558\uB294\uB370, \uC774 \uACBD\uC6B0\uAC00 \uBCF4\uD1B5 \uAC00\uC7A5 \uC88B\uC740 \uB2F5\uC744 \uC90D\uB2C8\uB2E4. \uACF5\uAE09\uC790\uAC00 \uC751\uB2F5\uC5D0 \uC6D0\uBCF8 \uCD94\uB860 \uD14D\uC2A4\uD2B8\uB97C \uC11E\uC5B4 \uB123\uACE0 \uAE54\uB054\uD55C \uB2F5\uC744 \uC6D0\uD560 \uB54C\uB9CC \uCF1C\uC138\uC694.",
